class Solution:
    def convertTime(self, current: str, correct: str) -> int:
        h1, m1 = map(int, current.split(':'))
        h2, m2 = map(int, correct.split(':'))
        d = h2 * 60 + m2 - (h1 * 60 + m1)
        steps = (60, 15, 5, 1)
        dp = [0] + [float('inf')] * d
        for x in range(1, d + 1):
            dp[x] = 1 + min(dp[x - s] for s in steps if s <= x)
        return dp[d]

